sponder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar dotación y presentación personal en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Dotación y presentación personal»?","respuesta":"La dotación protege el alimento de ti, no a ti del alimento. Por eso la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social es tan precisa sobre cómo debe ser. Vestimenta de trabajo (numerales 2 y 3) De color claro, para que se vea la suciedad; no se permiten grises ni tonos que la oculten. Con cierres o broches en lugar de botones, que pueden caer al alimento. Sin bolsillos por encima de la cintura. Con delantal bien atado. La empresa debe entregarla en cantidad suficiente.…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Dotación y presentación personal se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Higiene personal y prácticas higiénicas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente dotación y presentación personal en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de dotación y presentación personal"}],"keywords":["curso","manipulación","alimentos","dotación","presentación","personal","unidad","higiene","prácticas","higiénicas"],"mapa":{"centro":"Dotación y presentación personal","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 2. Higiene personal y prácticas higiénicas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Recibir y verificar","Almacenar por separado","Preparar con higiene"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro de recepción","Registro de almacenamiento","Registro de preparación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se protege un alimento en la práctica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Recibir y verificar","detalle":"Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento.","icono":"Search","evidencia":"Registro de recepción"},{"titulo":"Almacenar por separado","detalle":"Organiza crudos y listos para consumo para evitar contaminación cruzada.","icono":"ClipboardList","evidencia":"Registro de almacenamiento"},{"titulo":"Preparar con higiene","detalle":"Lava manos, utensilios y superficies; respeta tiempos y temperaturas.","icono":"Workflow","evidencia":"Registro de preparación"},{"titulo":"Controlar el proceso","detalle":"Mide los puntos críticos y corrige cualquier desviación antes de continuar.","icono":"FileCheck","evidencia":"Registro de control"},{"titulo":"Servir y conservar","detalle":"Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda.","icono":"RefreshCw","evidencia":"Registro de servicio"}]},"caso":{"titulo":"Dotación y presentación personal","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia aparece una situación que exige aplicar dotación y presentación personal con criterio y dejar evidencia.","pregunta":"¿Qué decisión demuestra que entendiste dotación y presentación personal?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
