  -- 06. Guantes, tapabocas y comportamientos prohibidos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Guantes, tapabocas y comportamientos prohibidos$t$
     AND m.title = $u$Unidad 2. Higiene personal y prácticas higiénicas$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Guantes, tapabocas y comportamientos prohibidos$t$, $u$Unidad 2. Higiene personal y prácticas higiénicas$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Guantes, tapabocas y comportamientos prohibidos","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un proveedor entrega un alimento a una temperatura fuera de rango. Lo que está en juego es el criterio de guantes, tapabocas y comportamientos prohibidos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar guantes, tapabocas y comportamientos prohibidos con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar guantes, tapabocas y comportamientos prohibidos con unidad 2. Higiene personal y prácticas higiénicas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar guantes, tapabocas y comportamientos prohibidos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, guantes, tapabocas y comportamientos prohibidos aparece en medio de una decisión que no admite improvisación: un proveedor entrega un alimento a una temperatura fuera de rango. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Higiene personal y prácticas higiénicas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en inocuidad y en contaminación cruzada, no en la intuición.","La clase pertenece a unidad 2. Higiene personal y prácticas higiénicas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar guantes, tapabocas y comportamientos prohibidos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Recibir y verificar. Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento. Evidencia que debe quedar: Registro de recepción.","Almacenar por separado. Organiza crudos y listos para consumo para evitar contaminación cruzada. Evidencia que debe quedar: Registro de almacenamiento.","Preparar con higiene. Lava manos, utensilios y superficies; respeta tiempos y temperaturas. Evidencia que debe quedar: Registro de preparación.","Controlar el proceso. Mide los puntos críticos y corrige cualquier desviación antes de continuar. Evidencia que debe quedar: Registro de control.","Servir y conservar. Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda. Evidencia que debe quedar: Registro de servicio.","Antes de cerrar la clase, pregúntate: ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar guantes, tapabocas y comportamientos prohibidos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Guantes, tapabocas y comportamientos prohibidos»?","respuesta":"Los elementos de protección ayudan, pero solo si se usan bien. La Resolución 2674 de 2013 del Ministerio de Salud y Protección Social lo deja claro en el artículo 14. Guantes (numeral 10) Si se usan, deben estar limpios y sin roturas, y recibir el mismo cuidado que las manos. Usar guantes no reemplaza el lavado de manos. Un guante que tocó dinero, el celular o carne cruda contamina igual que una mano sucia: se cambia. Tapabocas (numeral 6) Se usa tapabocas desechable cuando el riesgo lo exija,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Guantes, tapabocas y comportamientos prohibidos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Higiene personal y prácticas higiénicas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente guantes, tapabocas y comportamientos prohibidos en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de guantes, tapabocas y comportamientos prohibidos"}],"keywords":["curso","manipulación","alimentos","guantes","tapabocas","comportamientos","prohibidos","unidad","higiene","personal","prácticas","higiénicas"],"mapa":{"centro":"Guantes, tapabocas y comportamientos prohibidos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 2. Higiene personal y prácticas higiénicas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Recibir y verificar","Almacenar por separado","Preparar con higiene"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro de recepción","Registro de almacenamiento","Registro de preparación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se protege un alimento en la práctica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Recibir y verificar","detalle":"Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento.","icono":"Search","evidencia":"Registro de recepción"},{"titulo":"Almacenar por separado","detalle":"Organiza crudos y listos para consumo para evitar contaminación cruzada.","icono":"ClipboardList","evidencia":"Registro de almacenamiento"},{"titulo":"Preparar con higiene","detalle":"Lava manos, utensilios y superficies; respeta tiempos y temperaturas.","icono":"Workflow","evidencia":"Registro de preparación"},{"titulo":"Controlar el proceso","detalle":"Mide los puntos críticos y corrige cualquier desviación antes de continuar.","icono":"FileCheck","evidencia":"Registro de control"},{"titulo":"Servir y conservar","detalle":"Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda.","icono":"RefreshCw","evidencia":"Registro de servicio"}]},"caso":{"titulo":"Guantes, tapabocas y comportamientos prohibidos","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia aparece una situación que exige aplicar guantes, tapabocas y comportamientos prohibidos con criterio y dejar evidencia.","pregunta":"¿Qué decisión demuestra que entendiste guantes, tapabocas y comportamientos prohibidos?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
