  -- 09. Temperaturas seguras: la zona de peligro
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Temperaturas seguras: la zona de peligro$t$
     AND m.title = $u$Unidad 3. Las cinco claves y el control de temperaturas$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Temperaturas seguras: la zona de peligro$t$, $u$Unidad 3. Las cinco claves y el control de temperaturas$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Temperaturas seguras: la zona de peligro","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, la nevera se dañó durante la noche y nadie registró la temperatura. Lo que está en juego es el criterio de temperaturas seguras: la zona de peligro. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar temperaturas seguras: la zona de peligro con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar temperaturas seguras: la zona de peligro con unidad 3. Las cinco claves y el control de temperaturas y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar temperaturas seguras: la zona de peligro y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, temperaturas seguras: la zona de peligro aparece en medio de una decisión que no admite improvisación: la nevera se dañó durante la noche y nadie registró la temperatura. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Las cinco claves y el control de temperaturas. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en inocuidad y en contaminación cruzada, no en la intuición.","La clase pertenece a unidad 3. Las cinco claves y el control de temperaturas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar temperaturas seguras: la zona de peligro, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Recibir y verificar. Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento. Evidencia que debe quedar: Registro de recepción.","Almacenar por separado. Organiza crudos y listos para consumo para evitar contaminación cruzada. Evidencia que debe quedar: Registro de almacenamiento.","Preparar con higiene. Lava manos, utensilios y superficies; respeta tiempos y temperaturas. Evidencia que debe quedar: Registro de preparación.","Controlar el proceso. Mide los puntos críticos y corrige cualquier desviación antes de continuar. Evidencia que debe quedar: Registro de control.","Servir y conservar. Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda. Evidencia que debe quedar: Registro de servicio.","Antes de cerrar la clase, pregúntate: ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confiar en el olor o el color Corrección: los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar temperaturas seguras: la zona de peligro en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Temperaturas seguras: la zona de peligro»?","respuesta":"Los microorganismos se multiplican con gran rapidez entre 5 °C y 60 °C : la OMS la llama zona de peligro . Por debajo de 5 °C o por encima de 60 °C el crecimiento se frena o se detiene, aunque algunos microorganismos aún crecen por debajo de 5 °C. Las reglas de la OMS No dejes alimentos cocinados a temperatura ambiente más de 2 horas . Refrigera lo antes posible los alimentos cocinados y perecederos, de preferencia por debajo de 5 °C . Mantén la comida caliente a más de 60 °C antes de servirla. No guardes alimentos mucho tiempo,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Temperaturas seguras: la zona de peligro se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Las cinco claves y el control de temperaturas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente temperaturas seguras: la zona de peligro en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de temperaturas seguras: la zona de peligro"}],"keywords":["curso","manipulación","alimentos","temperaturas","seguras","peligro","unidad","cinco","claves","control"],"mapa":{"centro":"Temperaturas seguras: la zona de peligro","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 3. Las cinco claves y el control de temperaturas","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Recibir y verificar","Almacenar por separado","Preparar con higiene"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro de recepción","Registro de almacenamiento","Registro de preparación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se protege un alimento en la práctica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Recibir y verificar","detalle":"Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento.","icono":"Search","evidencia":"Registro de recepción"},{"titulo":"Almacenar por separado","detalle":"Organiza crudos y listos para consumo para evitar contaminación cruzada.","icono":"ClipboardList","evidencia":"Registro de almacenamiento"},{"titulo":"Preparar con higiene","detalle":"Lava manos, utensilios y superficies; respeta tiempos y temperaturas.","icono":"Workflow","evidencia":"Registro de preparación"},{"titulo":"Controlar el proceso","detalle":"Mide los puntos críticos y corrige cualquier desviación antes de continuar.","icono":"FileCheck","evidencia":"Registro de control"},{"titulo":"Servir y conservar","detalle":"Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda.","icono":"RefreshCw","evidencia":"Registro de servicio"}]},"caso":{"titulo":"Temperaturas seguras: la zona de peligro","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia aparece una situación que exige aplicar temperaturas seguras: la zona de peligro con criterio y dejar evidencia.","pregunta":"¿Qué decisión demuestra que entendiste temperaturas seguras: la zona de peligro?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
