    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 12. Agua potable y materias primas seguras
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Agua potable y materias primas seguras$t$
     AND m.title = $u$Unidad 4. Plan de saneamiento$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Agua potable y materias primas seguras$t$, $u$Unidad 4. Plan de saneamiento$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Agua potable y materias primas seguras","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, la nevera se dañó durante la noche y nadie registró la temperatura. Lo que está en juego es el criterio de agua potable y materias primas seguras. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar agua potable y materias primas seguras con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar agua potable y materias primas seguras con unidad 4. Plan de saneamiento y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar agua potable y materias primas seguras y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"La quinta clave de la OMS es usar agua y materias primas seguras . El agua es un ingrediente, aunque no se vea. Dónde se usa el agua La OMS recuerda que se necesita agua segura para lavar frutas y verduras, agregarla a los alimentos, preparar bebidas, hacer hielo, limpiar utensilios y lavarse las manos. El hielo hecho con agua no potable contamina una bebida que, por lo demás, era segura. El programa de agua potable El artículo 26 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige documentar la fuente del agua,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, agua potable y materias primas seguras aparece en medio de una decisión que no admite improvisación: la nevera se dañó durante la noche y nadie registró la temperatura. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Plan de saneamiento. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: La quinta clave de la OMS es usar agua y materias primas seguras . El agua es un ingrediente, aunque no se vea. Dónde se usa el agua La OMS recuerda que se necesita agua segura para lavar frutas y verduras, agregarla a los alimentos, preparar bebidas, hacer hielo, limpiar utensilios y lavarse las manos. El hielo hecho con agua no potable contamina una bebida que, por lo demás, era segura. El programa de agua potable El artículo 26 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige documentar la fuente del agua,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en inocuidad y en contaminación cruzada, no en la intuición.","La clase pertenece a unidad 4. Plan de saneamiento y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar agua potable y materias primas seguras, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Recibir y verificar. Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento. Evidencia que debe quedar: Registro de recepción.","Almacenar por separado. Organiza crudos y listos para consumo para evitar contaminación cruzada. Evidencia que debe quedar: Registro de almacenamiento.","Preparar con higiene. Lava manos, utensilios y superficies; respeta tiempos y temperaturas. Evidencia que debe quedar: Registro de preparación.","Controlar el proceso. Mide los puntos críticos y corrige cualquier desviación antes de continuar. Evidencia que debe quedar: Registro de control.","Servir y conservar. Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda. Evidencia que debe quedar: Registro de servicio.","Antes de cerrar la clase, pregúntate: ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar agua potable y materias primas seguras en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Agua potable y materias primas seguras»?","respuesta":"La quinta clave de la OMS es usar agua y materias primas seguras . El agua es un ingrediente, aunque no se vea. Dónde se usa el agua La OMS recuerda que se necesita agua segura para lavar frutas y verduras, agregarla a los alimentos, preparar bebidas, hacer hielo, limpiar utensilios y lavarse las manos. El hielo hecho con agua no potable contamina una bebida que, por lo demás, era segura. El programa de agua potable El artículo 26 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social exige documentar la fuente del agua,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Agua potable y materias primas seguras se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Plan de saneamiento.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente agua potable y materias primas seguras en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de agua potable y materias primas seguras"}],"keywords":["curso","manipulación","alimentos","potable","materias","primas","seguras","unidad","saneamiento"],"mapa":{"centro":"Agua potable y materias primas seguras","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 4. Plan de saneamiento","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Recibir y verificar","Almacenar por separado","Preparar con higiene"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro de recepción","Registro de almacenamiento","Registro de preparación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se protege un alimento en la práctica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Recibir y verificar","detalle":"Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento.","icono":"Search","evidencia":"Registro de recepción"},{"titulo":"Almacenar por separado","detalle":"Organiza crudos y listos para consumo para evitar contaminación cruzada.","icono":"ClipboardList","evidencia":"Registro de almacenamiento"},{"titulo":"Preparar con higiene","detalle":"Lava manos, utensilios y superficies; respeta tiempos y temperaturas.","icono":"Workflow","evidencia":"Registro de preparación"},{"titulo":"Controlar el proceso","detalle":"Mide los puntos críticos y corrige cualquier desviación antes de continuar.","icono":"FileCheck","evidencia":"Registro de control"},{"titulo":"Servir y conservar","detalle":"Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda.","icono":"RefreshCw","evidencia":"Registro de servicio"}]},"caso":{"titulo":"Agua potable y materias primas seguras","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia aparece una situación que exige aplicar agua potable y materias primas seguras con criterio y dejar evidencia.","pregunta":"¿Qué decisión demuestra que entendiste agua potable y materias primas seguras?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
