  -- 13. Recepción de materias primas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Recepción de materias primas$t$
     AND m.title = $u$Unidad 5. Recepción, almacenamiento y registros$u$
