  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Registros, autocontrol y caso integrador","texto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia, un alimento listo para consumo queda junto a uno crudo en la nevera. Lo que está en juego es el criterio de registros, autocontrol y caso integrador. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar registros, autocontrol y caso integrador con tus propias palabras y reconocer por qué importa en curso de Manipulación de Alimentos.","Relacionar registros, autocontrol y caso integrador con unidad 5. Recepción, almacenamiento y registros y con las decisiones de el responsable de inocuidad y calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar registros, autocontrol y caso integrador y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El parágrafo 2 del artículo 13 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pide que el manipulador conozca los puntos de control a su cargo, cómo vigilarlos, sus límites y qué hacer si algo se sale del límite. Eso es el autocontrol: vigilar, registrar y corregir. Registros que suelen llevarse Temperaturas de neveras, congeladores y baños de María. Recepción de materias primas y rechazos. Limpieza y desinfección, con fecha y responsable. Inspección de plagas. Lavado de tanques y análisis del agua. Capacitación: asistencia,…"},{"icono":"ShieldCheck","termino":"Inocuidad","definicion":"La garantía de que el alimento no causará daño al consumidor cuando se prepara y consume de la forma prevista."},{"icono":"FileCheck","termino":"Contaminación cruzada","definicion":"El paso de microorganismos o residuos de un alimento, superficie o utensilio a otro."},{"icono":"Network","termino":"Punto crítico de control","definicion":"Una etapa del proceso en la que se puede prevenir, eliminar o reducir un peligro a un nivel aceptable."},{"icono":"ClipboardCheck","termino":"Cadena de frío","definicion":"El mantenimiento de la temperatura adecuada desde la recepción hasta el consumo."},{"icono":"RefreshCw","termino":"Buenas prácticas de higiene","definicion":"Las conductas de limpieza, lavado de manos y manejo de utensilios que evitan contaminar el alimento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un establecimiento que prepara, almacena o vende alimentos en Colombia, registros, autocontrol y caso integrador aparece en medio de una decisión que no admite improvisación: un alimento listo para consumo queda junto a uno crudo en la nevera. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 5. Recepción, almacenamiento y registros. El objetivo del curso es claro: Que el participante aplique las prácticas higiénicas, el control de temperaturas y el plan de saneamiento que exige la Resolución 2674 de 2013, y reconozca en su puesto de trabajo los puntos donde un alimento se puede contaminar y cómo evitarlo. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El parágrafo 2 del artículo 13 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pide que el manipulador conozca los puntos de control a su cargo, cómo vigilarlos, sus límites y qué hacer si algo se sale del límite. Eso es el autocontrol: vigilar, registrar y corregir. Registros que suelen llevarse Temperaturas de neveras, congeladores y baños de María. Recepción de materias primas y rechazos. Limpieza y desinfección, con fecha y responsable. Inspección de plagas. Lavado de tanques y análisis del agua. Capacitación: asistencia,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en inocuidad y en contaminación cruzada, no en la intuición.","La clase pertenece a unidad 5. Recepción, almacenamiento y registros y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar registros, autocontrol y caso integrador, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Recibir y verificar. Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento. Evidencia que debe quedar: Registro de recepción.","Almacenar por separado. Organiza crudos y listos para consumo para evitar contaminación cruzada. Evidencia que debe quedar: Registro de almacenamiento.","Preparar con higiene. Lava manos, utensilios y superficies; respeta tiempos y temperaturas. Evidencia que debe quedar: Registro de preparación.","Controlar el proceso. Mide los puntos críticos y corrige cualquier desviación antes de continuar. Evidencia que debe quedar: Registro de control.","Servir y conservar. Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda. Evidencia que debe quedar: Registro de servicio.","Antes de cerrar la clase, pregúntate: ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: guardar crudos junto a listos para consumo Corrección: la separación evita que los jugos contaminen alimentos que no volverán a cocinarse.","Error: no documentar la limpieza Corrección: sin registro no se puede demostrar que la limpieza se hizo y se verificó.","Error: romper la cadena de frío Corrección: una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar registros, autocontrol y caso integrador en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"]}],"errores":[{"error":"Guardar crudos junto a listos para consumo","correccion":"La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."},{"error":"Confiar en el olor o el color","correccion":"Los microorganismos patógenos no siempre cambian el olor ni el aspecto del alimento."},{"error":"Romper la cadena de frío","correccion":"Una temperatura fuera de rango durante demasiado tiempo permite el crecimiento microbiano."},{"error":"Lavar la carne cruda en el fregadero","correccion":"Las salpicaduras dispersan contaminación; se cocina a la temperatura adecuada."},{"error":"No documentar la limpieza","correccion":"Sin registro no se puede demostrar que la limpieza se hizo y se verificó."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Registros, autocontrol y caso integrador»?","respuesta":"El parágrafo 2 del artículo 13 de la Resolución 2674 de 2013 del Ministerio de Salud y Protección Social pide que el manipulador conozca los puntos de control a su cargo, cómo vigilarlos, sus límites y qué hacer si algo se sale del límite. Eso es el autocontrol: vigilar, registrar y corregir. Registros que suelen llevarse Temperaturas de neveras, congeladores y baños de María. Recepción de materias primas y rechazos. Limpieza y desinfección, con fecha y responsable. Inspección de plagas. Lavado de tanques y análisis del agua. Capacitación: asistencia,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Guardar crudos junto a listos para consumo La separación evita que los jugos contaminen alimentos que no volverán a cocinarse."}],"resumen":["Registros, autocontrol y caso integrador se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 5. Recepción, almacenamiento y registros.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué registro demuestra que el peligro se controló y que el alimento era seguro?"],"referencias":[{"cita":"INVIMA. Alimentos y bebidas: normatividad y conceptos sanitarios.","url":"https://www.invima.gov.co/"},{"cita":"Codex Alimentarius. Principios generales de higiene de los alimentos.","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/es/"},{"cita":"Organización Mundial de la Salud. Inocuidad de los alimentos.","url":"https://www.who.int/es/news-room/fact-sheets/detail/food-safety"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente registros, autocontrol y caso integrador en un establecimiento que prepara, almacena o vende alimentos en Colombia.","alt":"Ilustración de registros, autocontrol y caso integrador"}],"keywords":["curso","manipulación","alimentos","registros","autocontrol","integrador","unidad","recepción","almacenamiento"],"mapa":{"centro":"Registros, autocontrol y caso integrador","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad e inocuidad","Unidad 5. Recepción, almacenamiento y registros","Inocuidad"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Recibir y verificar","Almacenar por separado","Preparar con higiene"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro de recepción","Registro de almacenamiento","Registro de preparación"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Guardar crudos junto a listos para consumo","Confiar en el olor o el color","Romper la cadena de frío"]}]},"proceso":{"titulo":"Cómo se protege un alimento en la práctica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Recibir y verificar","detalle":"Revisa temperatura, empaque, etiqueta y proveedor antes de aceptar un alimento.","icono":"Search","evidencia":"Registro de recepción"},{"titulo":"Almacenar por separado","detalle":"Organiza crudos y listos para consumo para evitar contaminación cruzada.","icono":"ClipboardList","evidencia":"Registro de almacenamiento"},{"titulo":"Preparar con higiene","detalle":"Lava manos, utensilios y superficies; respeta tiempos y temperaturas.","icono":"Workflow","evidencia":"Registro de preparación"},{"titulo":"Controlar el proceso","detalle":"Mide los puntos críticos y corrige cualquier desviación antes de continuar.","icono":"FileCheck","evidencia":"Registro de control"},{"titulo":"Servir y conservar","detalle":"Mantén la temperatura, identifica alérgenos y guarda muestras cuando corresponda.","icono":"RefreshCw","evidencia":"Registro de servicio"}]},"caso":{"titulo":"Registros, autocontrol y caso integrador","contexto":"En un establecimiento que prepara, almacena o vende alimentos en Colombia aparece una situación que exige aplicar registros, autocontrol y caso integrador con criterio y dejar evidencia.","pregunta":"¿Qué decisión demuestra que entendiste registros, autocontrol y caso integrador?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases completas con experiencia interactiva (catálogo).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;
  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Manipulación de Alimentos$t$, v_n;
END $curso$;
